package com.portfolio.jobtracker.application;

import com.portfolio.jobtracker.application.dto.StatusCount;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.JpaSpecificationExecutor;
import org.springframework.data.jpa.repository.Query;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

/**
 * Data access for job applications (implementation generated by Spring Data JPA).
 *
 * <ul>
 *   <li>{@code JpaRepository} - standard CRUD + paging/sorting methods.</li>
 *   <li>{@code JpaSpecificationExecutor} - adds {@code findAll(Specification, Pageable)}, used for the
 *       dynamic search (see {@link JobApplicationSpecifications}).</li>
 * </ul>
 */
public interface JobApplicationRepository
        extends JpaRepository<JobApplication, Long>, JpaSpecificationExecutor<JobApplication> {

    /** Scoped by user so one user can never read or modify another user's data. */
    Optional<JobApplication> findByIdAndUserId(Long id, Long userId);

    long countByUserId(Long userId);

    /**
     * Counts applications per status IN THE DATABASE with GROUP BY, instead of loading every row
     * into Java and counting there. Written in JPQL (queries over entity classes, not tables).
     * {@code select new ...StatusCount(...)} builds a DTO directly from each result row.
     * {@code :userId} is a named parameter bound from the method argument (safe from SQL injection).
     */
    @Query("""
            select new com.portfolio.jobtracker.application.dto.StatusCount(a.status, count(a))
            from JobApplication a
            where a.user.id = :userId
            group by a.status
            """)
    List<StatusCount> countByStatus(Long userId);

    /** Only the dates are selected (not whole entities), which keeps the weekly-chart query light. */
    @Query("select a.appliedDate from JobApplication a where a.user.id = :userId and a.appliedDate >= :since")
    List<LocalDate> findAppliedDatesSince(Long userId, LocalDate since);
}
